declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$me=require_login();$cart=mp550_cart_details();if(!$cart['items']){header('Location: /cart.php');exit;}$err='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();try{$r=mp550_checkout((int)$me['id'],['name'=>$_POST['name']??$me['name'],'phone'=>$_POST['phone']??($me['phone']??''),'email'=>$_POST['email']??($me['email']??''),'address'=>$_POST['address']??'','note'=>$_POST['note']??''],(string)($_POST['payment_method']??'cod'),'web');$_SESSION['mp550_checkout_success']=$r;header('Location: /my-orders.php?placed=1&group='.urlencode($r['group']));exit;}catch(Throwable $e){$err=$e->getMessage();}}mp550_public_header('Checkout');
?>
<section class="mp550-page-head"><div><span>SECURE CHECKOUT</span><h1>Place your marketplace order.</h1><p>Products are automatically routed to the correct seller/shop.</p></div><b><?=mp550_money((float)$cart['grand_total'])?></b></section><?php if($err):?><div class="mp550-alert err"><?=e($err)?></div><?php endif;?><form method="post" class="mp550-checkout"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><section><h2>Delivery information</h2><label>Name<input name="name" required value="<?=e($me['name'])?>"></label><div class="two"><label>Phone<input name="phone" required value="<?=e((string)($me['phone']??''))?>"></label><label>Email<input type="email" name="email" value="<?=e((string)($me['email']??''))?>"></label></div><label>Delivery address<textarea name="address" required rows="4" placeholder="House/shop, street, area, city"></textarea></label><label>Order note<textarea name="note" rows="3" placeholder="Optional delivery instructions"></textarea></label><h2>Payment</h2><div class="payment-options"><?php if(setting_bool('marketplace_v550_allow_cod',true)):?><label><input type="radio" name="payment_method" value="cod" checked><span><b>Cash on Delivery</b><small>Pay when your order arrives.</small></span></label><?php endif;?><?php if(setting_bool('marketplace_v550_allow_advance',true)):?><label><input type="radio" name="payment_method" value="advance"><span><b>Advance / Online Payment</b><small>Creates a payment order through configured payment system.</small></span></label><?php endif;?><?php if(setting_bool('marketplace_v550_allow_bank_transfer',true)):?><label><input type="radio" name="payment_method" value="bank_transfer"><span><b>Bank Transfer</b><small>Seller/admin can confirm payment after transfer.</small></span></label><?php endif;?></div></section><aside><h2>Review</h2><?php foreach($cart['items'] as $it):?><div class="review-item"><span><?=e($it['product']['title'])?> × <?=(int)$it['qty']?></span><b><?=mp550_money((float)$it['line_tota